// lib/run/lang/pascal.driver.ts
function pasStr(s) {
  const pieces = [];
  let cur = "";
  let run = "";
  const endRun = () => {
    if (run) cur += `'${run}'`;
    run = "";
  };
  for (const ch of String(s ?? "")) {
    const cp = ch.codePointAt(0) ?? 0;
    if (cp >= 32 && cp <= 126) run += ch === "'" ? "''" : ch;
    else {
      endRun();
      cur += utf8Bytes(ch).map((b) => `#${b}`).join("");
    }
    if (cur.length + run.length >= 60) {
      endRun();
      pieces.push(cur);
      cur = "";
    }
  }
  endRun();
  if (cur) pieces.push(cur);
  return pieces.length ? pieces.join(" +\n      ") : "''";
}
function pasLit(t, v) {
  switch (t.k) {
    case "int":
      return intText(v);
    case "float":
      return floatText(v);
    case "bool":
      return v ? "True" : "False";
    case "str":
      return pasStr(String(v ?? ""));
    case "list": {
      const a = Array.isArray(v) ? v : [];
      const items = a.map((x) => pasLit(t.el, x));
      const lines = [];
      for (let i = 0; i < items.length; i += 12) lines.push(items.slice(i, i + 12).join(", "));
      return `[${lines.join(",\n      ")}]`;
    }
    default:
      return "Null";
  }
}
